       WHERE R.CLASSIFICATION_CODE='ISIC' AND R.REVISION_CODE='4' AND R.VARIANT_CODE='UNSD' AND R.COUNTRY_CODE IS NULL) S
ON (T.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND T.ISIC_CODE='013')
WHEN MATCHED THEN UPDATE SET
    T.PARENT_ACTIVITY_ID=(SELECT P.ISIC_ACTIVITY_ID FROM CIF.REF_ISIC_ACTIVITY2 P WHERE P.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND P.ISIC_CODE='01'), T.LEVEL_CODE='GROUP', T.LEVEL_NO=3,
    T.NAME_FA='تکثیر گیاهان', T.NAME_EN='Plant propagation', T.TRANSLATION_STATUS_CODE='BANK_TRANSLATED',
    T.IS_SELECTABLE=0, T.IS_ACTIVE=1, T.SORT_ORDER=210,
    T.LAST_MODIFIED_BY='SEED', T.LAST_MODIFIED_DATE=SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT
    (ISIC_RELEASE_ID,PARENT_ACTIVITY_ID,ISIC_CODE,LEVEL_CODE,LEVEL_NO,NAME_FA,NAME_EN,TRANSLATION_STATUS_CODE,
     IS_SELECTABLE,IS_ACTIVE,SORT_ORDER,RECORD_VERSION,CREATED_BY)
VALUES
    (S.ISIC_RELEASE_ID,(SELECT P.ISIC_ACTIVITY_ID FROM CIF.REF_ISIC_ACTIVITY2 P WHERE P.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND P.ISIC_CODE='01'),'013','GROUP',3,'تکثیر گیاهان','Plant propagation','BANK_TRANSLATED',0,1,210,1,'SEED');

