       WHERE R.CLASSIFICATION_CODE='ISIC' AND R.REVISION_CODE='4' AND R.VARIANT_CODE='UNSD' AND R.COUNTRY_CODE IS NULL) S
ON (T.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND T.ISIC_CODE='6202')
WHEN MATCHED THEN UPDATE SET
    T.PARENT_ACTIVITY_ID=(SELECT P.ISIC_ACTIVITY_ID FROM CIF.REF_ISIC_ACTIVITY2 P WHERE P.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND P.ISIC_CODE='620'), T.LEVEL_CODE='CLASS', T.LEVEL_NO=4,
    T.NAME_FA='مشاوره رایانه و فعالیت‌های مدیریت تأسیسات رایانه‌ای', T.NAME_EN='Computer consultancy and computer facilities management activities', T.TRANSLATION_STATUS_CODE='BANK_TRANSLATED',
    T.IS_SELECTABLE=1, T.IS_ACTIVE=1, T.SORT_ORDER=5230,
    T.LAST_MODIFIED_BY='SEED', T.LAST_MODIFIED_DATE=SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT
    (ISIC_RELEASE_ID,PARENT_ACTIVITY_ID,ISIC_CODE,LEVEL_CODE,LEVEL_NO,NAME_FA,NAME_EN,TRANSLATION_STATUS_CODE,
     IS_SELECTABLE,IS_ACTIVE,SORT_ORDER,RECORD_VERSION,CREATED_BY)
VALUES
    (S.ISIC_RELEASE_ID,(SELECT P.ISIC_ACTIVITY_ID FROM CIF.REF_ISIC_ACTIVITY2 P WHERE P.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND P.ISIC_CODE='620'),'6202','CLASS',4,'مشاوره رایانه و فعالیت‌های مدیریت تأسیسات رایانه‌ای','Computer consultancy and computer facilities management activities','BANK_TRANSLATED',1,1,5230,1,'SEED');

